local RunService = game:GetService("RunService")
local pg

local function set(o,k,v)
 if v~=nil then pcall(function() o[k]=v end) end
end
local function enum(t,n)
 local aliases={UIGradientTileMode="GradientTileMode",UIGradientType="GradientType"}
 t=aliases[t] or t
 local ok,group=pcall(function() return Enum[t] end)
 if not ok or group==nil then return nil end
 local valid,items=pcall(function() return group:GetEnumItems() end)
 if not valid or not items then return nil end
 for _,v in ipairs(items) do if v.Value==n then return v end end
 return nil
end

