local function setupNeonNotifications(gui)
 local TweenService = game:GetService("TweenService")
 local activeGreen = Color3.fromRGB(65,232,134)
 local inactiveRed = Color3.fromRGB(245,77,111)
 local function make(class,name,parent)
  local o=Instance.new(class)
  o.Name=name
  o.Parent=parent
  return o
 end
 local function rounded(parent,r)
  local c=parent:FindFirstChildOfClass("UICorner") or make("UICorner","Corner",parent)
  c.CornerRadius=UDim.new(0,r)
  return c
 end
 local layer=gui:FindFirstChild("NotificationLayer") or make("Frame","NotificationLayer",gui)
 layer.AnchorPoint=Vector2.new(1,0)
 layer.Position=UDim2.new(1,-18,0,88)
 layer.Size=UDim2.fromOffset(296,184)
 layer.BackgroundTransparency=1
 layer.BorderSizePixel=0
 layer.ClipsDescendants=false
 layer.ZIndex=500

 local scale=layer:FindFirstChild("NotificationScale") or make("UIScale","NotificationScale",layer)
 local function fit()
  local cam=workspace.CurrentCamera
  if cam then scale.Scale=math.clamp((cam.ViewportSize.X-32)/304,0.67,1) end
 end
 fit()
 local cam=workspace.CurrentCamera
 local fitConn=cam and cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)

 local template=layer:FindFirstChild("NotificationTemplate") or make("Frame","NotificationTemplate",layer)
 for _,child in ipairs(template:GetChildren()) do child:Destroy() end
 template.AnchorPoint=Vector2.new(1,0)
 template.Position=UDim2.new(1,0,0,0)
 template.Size=UDim2.fromOffset(292,52)
 template.BackgroundColor3=Color3.fromRGB(24,24,29)
 template.BackgroundTransparency=0.07
 template.BorderSizePixel=0
 template.ZIndex=502
 template.Visible=false
 rounded(template,9)
 local surface=make("UIGradient","DarkSurface",template)
 surface.Color=ColorSequence.new(Color3.fromRGB(37,37,43),Color3.fromRGB(19,20,25))
 surface.Rotation=8
 local stroke=make("UIStroke","NeonStroke",template)
 stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
 stroke.Thickness=1.15
 stroke.Transparency=0.45
 stroke.Color=activeGreen
 local neon=make("UIGradient","NeonCycle",stroke)
 neon.Color=ColorSequence.new({
  ColorSequenceKeypoint.new(0,Color3.fromRGB(28,103,66)),
  ColorSequenceKeypoint.new(0.40,Color3.fromRGB(90,245,160)),
  ColorSequenceKeypoint.new(0.70,Color3.fromRGB(31,107,71)),
  ColorSequenceKeypoint.new(1,Color3.fromRGB(28,103,66))
 })
 local outer=make("UIStroke","NeonOuterGlow",template)
 outer.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
 outer.Thickness=2.7
 outer.Transparency=0.94
 outer.Color=activeGreen
 local accent=make("Frame","AccentBar",template)
 accent.Position=UDim2.fromOffset(3,12)
 accent.Size=UDim2.fromOffset(2,28)
 accent.BackgroundColor3=activeGreen
 accent.BackgroundTransparency=0.20
 accent.BorderSizePixel=0
 accent.ZIndex=504
 rounded(accent,2)
 local iconBox=make("Frame","IconBox",template)
 iconBox.Position=UDim2.fromOffset(13,10)
 iconBox.Size=UDim2.fromOffset(32,32)
 iconBox.BackgroundColor3=Color3.fromRGB(42,43,48)
 iconBox.BackgroundTransparency=0.1
 iconBox.BorderSizePixel=0
 iconBox.ZIndex=504
 rounded(iconBox,8)
 local dot=make("Frame","StatusDot",iconBox)
 dot.AnchorPoint=Vector2.new(0.5,0.5)
 dot.Position=UDim2.fromScale(0.5,0.5)
 dot.Size=UDim2.fromOffset(9,9)
 dot.BackgroundColor3=activeGreen
 dot.BorderSizePixel=0
 dot.ZIndex=505
 rounded(dot,20)
 local dotStroke=make("UIStroke","DotGlow",dot)
 dotStroke.Thickness=2.5
 dotStroke.Color=activeGreen
 dotStroke.Transparency=0.82
 local title=make("TextLabel","StateTitle",template)
 title.BackgroundTransparency=1
 title.Position=UDim2.fromOffset(56,9)
 title.Size=UDim2.new(1,-68,0,17)
 local headingFont=gui.MainWindow.Header.BrandText.FontFace
 title.FontFace=headingFont
 title.RichText=true
 title.Text='<font color="#F1EDF0">DANLO</font> <font color="#EC4254">HUB</font>'
 title.TextColor3=Color3.fromRGB(240,239,245)
 title.TextSize=12
 title.TextXAlignment=Enum.TextXAlignment.Left
 title.ZIndex=505
 local detail=make("TextLabel","StateDetail",template)
 detail.BackgroundTransparency=1
 detail.Position=UDim2.fromOffset(56,27)
 detail.Size=UDim2.new(1,-68,0,16)
 detail.FontFace=headingFont
 detail.Text="Interruptor de ejemplo activado"
 detail.TextColor3=Color3.fromRGB(183,183,194)
 detail.TextSize=11
 detail.TextXAlignment=Enum.TextXAlignment.Left
 detail.TextTruncate=Enum.TextTruncate.AtEnd
 detail.ZIndex=505

 local event=gui:FindFirstChild("Notify") or make("BindableEvent","Notify",gui)
 local notifications={}
 local function reposition()
  for i,item in ipairs(notifications) do
   if item.Parent then
    TweenService:Create(item,TweenInfo.new(0.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
     {Position=UDim2.new(1,0,0,(i-1)*59)}):Play()
   end
  end
 end
 local function remove(item)
  for i,obj in ipairs(notifications) do
   if obj==item then table.remove(notifications,i) break end
  end
  if item.Parent then item:Destroy() end
  reposition()
 end
 local function display(enabled,name)
  local action=type(enabled)=="string" and string.lower(enabled) or ""
  local isExecute=(action=="execute" or action=="ejecutar")
  local isOpen=(action=="open" or action=="abrir")
  local isOn=(enabled==true or action=="on" or action=="success")
  local positive=isOn or isExecute or isOpen
  local c=positive and activeGreen or inactiveRed
  local textName=type(name)=="string" and name:match("^%s*(.-)%s*$") or ""
  if textName=="" then textName="Función" end
  local toast=template:Clone()
  toast.Name="NotificationActive"
  toast.Visible=true
  toast.Parent=layer
  toast.Position=UDim2.new(1,310,0,0)
  toast.NeonStroke.Color=c
  toast.NeonOuterGlow.Color=c
  toast.AccentBar.BackgroundColor3=c
  toast.IconBox.StatusDot.BackgroundColor3=c
  toast.IconBox.StatusDot.DotGlow.Color=c
  if isExecute then
   toast.StateDetail.Text=(textName=="Función") and "Ejecutando" or ("Ejecutando "..textName)
  elseif isOpen then
   toast.StateDetail.Text=(textName=="Función") and "Abriendo" or ("Abriendo "..textName)
  else
   toast.StateDetail.Text=textName..(isOn and " activado" or " desactivado")
  end
  toast.StateDetail.TextColor3=(isExecute or isOpen) and Color3.fromRGB(126,255,174) or Color3.fromRGB(183,183,194)
  local dark=positive and Color3.fromRGB(34,105,73) or Color3.fromRGB(119,38,57)
  local bright=positive and Color3.fromRGB(100,248,167) or Color3.fromRGB(255,111,144)
  toast.NeonStroke.NeonCycle.Color=ColorSequence.new({
   ColorSequenceKeypoint.new(0,dark),
   ColorSequenceKeypoint.new(0.42,bright),
   ColorSequenceKeypoint.new(0.72,dark),
   ColorSequenceKeypoint.new(1,dark)
  })
  table.insert(notifications,1,toast)
  if #notifications>3 then remove(notifications[#notifications]) end
  reposition()
  local spinning=TweenService:Create(toast.NeonStroke.NeonCycle,
   TweenInfo.new(3.5,Enum.EasingStyle.Linear,Enum.EasingDirection.InOut,-1),{Rotation=360})
  spinning:Play()
  task.delay(2.85,function()
   if not toast.Parent then spinning:Cancel() return end
   local out=TweenService:Create(toast,TweenInfo.new(0.25,Enum.EasingStyle.Quad,Enum.EasingDirection.In),
    {Position=UDim2.new(1,310,0,toast.Position.Y.Offset)})
   out:Play()
   out.Completed:Wait()
   spinning:Cancel()
   remove(toast)
  end)
 end
 local eventConn=event.Event:Connect(display)
 return event,function()
  if fitConn then fitConn:Disconnect() end
  if eventConn then eventConn:Disconnect() end
 end
end


local ACTIVE_GREEN=Color3.fromRGB(84,255,165)
local INACTIVE_RED=Color3.fromRGB(255,151,180)
local BACK_GREEN=Color3.fromRGB(14,72,47)
local BACK_RED=Color3.fromRGB(59,15,41)
local BORDER_GREEN=Color3.fromRGB(51,231,142)
local BORDER_RED=Color3.fromRGB(242,70,110)
local GREEN_FLOW=ColorSequence.new({
 ColorSequenceKeypoint.new(0,Color3.fromRGB(11,71,45)),
 ColorSequenceKeypoint.new(0.38,Color3.fromRGB(95,255,171)),
 ColorSequenceKeypoint.new(0.68,Color3.fromRGB(19,132,82)),
 ColorSequenceKeypoint.new(1,Color3.fromRGB(11,71,45))
})
local RED_FLOW=ColorSequence.new({
 ColorSequenceKeypoint.new(0,Color3.fromRGB(68,20,49)),
 ColorSequenceKeypoint.new(0.38,Color3.fromRGB(255,124,163)),
 ColorSequenceKeypoint.new(0.68,Color3.fromRGB(182,35,85)),
 ColorSequenceKeypoint.new(1,Color3.fromRGB(68,20,49))
})
local function styleButton(button,caption,on)
 button.Text=caption
 TweenService:Create(button,TweenInfo.new(0.15,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{
  BackgroundColor3=on and BACK_GREEN or BACK_RED,
  TextColor3=on and ACTIVE_GREEN or INACTIVE_RED
 }):Play()
 local stroke=button:FindFirstChildOfClass("UIStroke")
 if stroke then
  stroke.Color=on and BORDER_GREEN or BORDER_RED
  local grad=stroke:FindFirstChild("NeonFlow")
  if grad and grad:IsA("UIGradient") then grad.Color=on and GREEN_FLOW or RED_FLOW end
 end
end
local function cfgTable(arg)
 if type(arg)=="string" then return {Name=arg} end
 assert(type(arg)=="table","Se esperaba una tabla de configuración o un nombre")
 return arg
end
local function safeCall(callback,...)
 if type(callback)~="function" then return true end
 local ok,err=pcall(callback,...)
 if not ok then warn("[DanloUI] Error en Callback: "..tostring(err)) end
 return ok
end
local function makeName(name)
 return (tostring(name or "FUNCION"):gsub("^%s+",""):gsub("%s+$",""))
end
local function setCardText(card,kind,cfg)
 local name=makeName(cfg.Name or cfg.Title or kind)
 card.FeatureTitle.Text=name
 card.FeatureSummary.Text=tostring(cfg.Description or cfg.Desc or "")
 card.FeatureTitle.TextTruncate=Enum.TextTruncate.AtEnd
 card.FeatureSummary.TextTruncate=Enum.TextTruncate.AtEnd
 return name
end

local function stylePremiumTag(header)
 local tag=header:FindFirstChild("PremiumTag")
 if not tag then return {} end

 tag.Position=UDim2.fromOffset(600,19)
 tag.Size=UDim2.fromOffset(124,28)
 tag.BackgroundColor3=Color3.fromRGB(22,8,17)
 tag.BackgroundTransparency=0
 tag.BorderSizePixel=0
 tag.ClipsDescendants=false
 tag.ZIndex=5
 local radius=tag:FindFirstChildOfClass("UICorner")
 if radius then radius.CornerRadius=UDim.new(0,7) end
 for _,old in ipairs(tag:GetChildren()) do
  if old.Name=="PremiumFill" or old.Name=="PremiumRedBorder" or
     old.Name=="PremiumOuterGlow" or old.Name=="PremiumTextGlow" or
     old.Name=="Crown" or old.Name=="CrownGlow" or old.Name=="PremiumCrown" or
     old.Name=="PremiumSeparator" then
   old:Destroy()
  end
 end

 local fill=Instance.new("UIGradient")
 fill.Name="PremiumFill"
 fill.Color=ColorSequence.new({
  ColorSequenceKeypoint.new(0,Color3.fromRGB(22,7,18)),
  ColorSequenceKeypoint.new(0.48,Color3.fromRGB(58,11,31)),
  ColorSequenceKeypoint.new(1,Color3.fromRGB(25,7,20))
 })
 fill.Rotation=0
 fill.Parent=tag

 local halo=Instance.new("UIStroke")
 halo.Name="PremiumOuterGlow"
 halo.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
 halo.Color=Color3.fromRGB(245,23,76)
 halo.Thickness=3
 halo.Transparency=0.86
 halo.Parent=tag

 local border=Instance.new("UIStroke")
 border.Name="PremiumRedBorder"
 border.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
 border.Color=Color3.fromRGB(255,56,103)
 border.Thickness=1.3
 border.Transparency=0.12
 border.Parent=tag
 local borderGradient=Instance.new("UIGradient")
 borderGradient.Name="NeonFlow"
 borderGradient.Color=ColorSequence.new({
  ColorSequenceKeypoint.new(0,Color3.fromRGB(178,33,69)),
  ColorSequenceKeypoint.new(0.35,Color3.fromRGB(255,86,126)),
  ColorSequenceKeypoint.new(0.50,Color3.fromRGB(255,159,178)),
  ColorSequenceKeypoint.new(0.72,Color3.fromRGB(255,62,110)),
  ColorSequenceKeypoint.new(1,Color3.fromRGB(176,33,74))
 })
 borderGradient.Parent=border

 local label=tag:FindFirstChild("TagText")
 if label then
  label.Position=UDim2.fromOffset(45,0)
  label.Size=UDim2.fromOffset(74,28)
  label.BackgroundTransparency=1
  label.Text="PREMIUN"
  label.TextScaled=false
  label.TextSize=11
  label.FontFace=Font.new("rbxasset://fonts/families/GothamSSm.json",Enum.FontWeight.Bold,Enum.FontStyle.Normal)
  label.TextColor3=Color3.fromRGB(255,139,166)
  label.TextStrokeTransparency=1
  label.TextTransparency=0
  label.TextXAlignment=Enum.TextXAlignment.Center
  label.TextYAlignment=Enum.TextYAlignment.Center
  label.ZIndex=8
 end

 local separator=Instance.new("Frame")
 separator.Name="PremiumSeparator"
 separator.Size=UDim2.fromOffset(1,14)
 separator.Position=UDim2.fromOffset(39,7)
 separator.BackgroundColor3=Color3.fromRGB(182,49,86)
 separator.BackgroundTransparency=0.52
 separator.BorderSizePixel=0
 separator.ZIndex=7
 separator.Parent=tag

 local crown=Instance.new("Frame")
 crown.Name="PremiumCrown"
 crown.BackgroundTransparency=1
 crown.BorderSizePixel=0
 crown.Position=UDim2.fromOffset(8,5)
 crown.Size=UDim2.fromOffset(26,19)
 crown.ZIndex=8
 crown.Parent=tag

 local red=Color3.fromRGB(255,87,127)
 local highlight=Color3.fromRGB(255,167,187)
 local twinkle={}
 local function line(x1,y1,x2,y2,thick,color,alpha,z)
  local dx,dy=x2-x1,y2-y1
  local segment=Instance.new("Frame")
  segment.Name="CrownStroke"
  segment.AnchorPoint=Vector2.new(0.5,0.5)
  segment.Position=UDim2.fromOffset((x1+x2)*0.5,(y1+y2)*0.5)
  segment.Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),thick)
  segment.Rotation=math.deg(math.atan2(dy,dx))
  segment.BackgroundColor3=color
  segment.BackgroundTransparency=alpha
  segment.BorderSizePixel=0
  segment.ZIndex=z
  segment.Parent=crown
  local corners=Instance.new("UICorner")
  corners.CornerRadius=UDim.new(1,0)
  corners.Parent=segment
  return segment
 end
 local edges={
  {2,4,6,14},
  {6,14,13,3},
  {13,3,20,14},
  {20,14,24,4},
  {6,14,5,17},
  {20,14,21,17},
  {5,17,21,17}
 }
 for _,edge in ipairs(edges) do
  line(edge[1],edge[2],edge[3],edge[4],4.3,Color3.fromRGB(238,30,80),0.82,9)
  line(edge[1],edge[2],edge[3],edge[4],1.8,red,0,10)
 end
 for _,point in ipairs({{2,4},{13,3},{24,4}}) do
  local gem=Instance.new("Frame")
  gem.Name="CrownJewel"
  gem.AnchorPoint=Vector2.new(0.5,0.5)
  gem.Position=UDim2.fromOffset(point[1],point[2])
  gem.Size=UDim2.fromOffset(3.6,3.6)
  gem.BackgroundColor3=highlight
  gem.BorderSizePixel=0
  gem.ZIndex=11
  gem.Parent=crown
  local round=Instance.new("UICorner")
  round.CornerRadius=UDim.new(1,0)
  round.Parent=gem
  table.insert(twinkle,gem)
 end

 local pulse=TweenInfo.new(1.8,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true)
 local tweens={
  TweenService:Create(border,pulse,{Transparency=0,Color=Color3.fromRGB(255,111,149)}),
  TweenService:Create(halo,pulse,{Transparency=0.74}),
 }
 if label then
  table.insert(tweens,TweenService:Create(label,pulse,{TextColor3=Color3.fromRGB(255,185,202)}))
 end
 for _,gem in ipairs(twinkle) do
  table.insert(tweens,TweenService:Create(gem,pulse,{BackgroundColor3=Color3.fromRGB(255,208,219)}))
 end
 for _,tw in ipairs(tweens) do tw:Play() end
 return tweens
end

function DanloUI:CreateWindow(config)
 config=config or {}
 local player=Players.LocalPlayer
 assert(player,"DanloUI se crea solo desde un LocalScript del cliente")
 pg=player:WaitForChild("PlayerGui")
 if DanloUI._activeWindow then DanloUI._activeWindow:Destroy() end
 local previous=pg:FindFirstChild("DANLOHUB_PLANTILLA")
 if previous then previous:Destroy() end
 local gui=build()
 gui.Name="DanloUI_V1"
 gui.ResetOnSpawn=false
 for _,child in ipairs(pg:GetChildren()) do
  if child~=gui and child.Name=="DanloUI_V1" then child:Destroy() end
 end
 local window=gui:WaitForChild("MainWindow")
 local sidebar=window:WaitForChild("Sidebar")
 local header=window:WaitForChild("Header")
 local workspacePanel=window:WaitForChild("Workspace")
 local host=workspacePanel:WaitForChild("PageHost")
 local home=host:WaitForChild("Page_home")
 local samples=host:WaitForChild("Page_plantilla")
 local templates={
  Toggle=samples:WaitForChild("Card_Toggle"):Clone(),
  Slider=samples:WaitForChild("Card_Slider"):Clone(),
  Execute=samples:WaitForChild("Card_Execute"):Clone(),
  Open=samples:WaitForChild("Card_Open"):Clone()
 }
 local navTemplate=sidebar:WaitForChild("Nav_plantilla"):Clone()
 local pageTemplate=host:WaitForChild("Page_plantilla2"):Clone()
 local notifyEvent,stopNotifications=setupNeonNotifications(gui)
 local running=true
 local connections={}
 local tabs={}
 local activeId="home"
 local nextId=0
 local pageCards={}
 local animations=stylePremiumTag(header)
 local gradients={}
 local function keep(conn)
  table.insert(connections,conn)
  return conn
 end
 local function alive() return running and gui.Parent~=nil end
 local function notify(status,name)
  if alive() then notifyEvent:Fire(status,name) end
 end

 samples:Destroy()
 for _,key in ipairs({"plantilla2","plantilla3"}) do
  local page=host:FindFirstChild("Page_"..key)
  if page then page:Destroy() end
 end
 for _,key in ipairs({"plantilla","plantilla2","plantilla3"}) do
  local nav=sidebar:FindFirstChild("Nav_"..key)
  if nav then nav:Destroy() end
 end
 local navArea=Instance.new("ScrollingFrame")
 navArea.Name="DanloNavigation"
 navArea.BackgroundTransparency=1
 navArea.BorderSizePixel=0
 navArea.Position=UDim2.fromOffset(0,43)
 navArea.Size=UDim2.new(1,0,0,351)
 navArea.ScrollBarThickness=2
 navArea.ScrollBarImageColor3=Color3.fromRGB(210,58,104)
 navArea.ScrollingDirection=Enum.ScrollingDirection.Y
 navArea.CanvasSize=UDim2.fromOffset(0,351)
 navArea.Parent=sidebar
 local navHome=sidebar:WaitForChild("Nav_home")
 navHome.Parent=navArea
 navHome.Position=UDim2.fromOffset(10,3)
 local sidebarTiles=home:WaitForChild("IconPalette")
 sidebarTiles.Visible=false
 local quicks={home:FindFirstChild("Quick_plantilla"),home:FindFirstChild("Quick_plantilla2"),home:FindFirstChild("Quick_plantilla3")}
 local quickAssigned={}
 local homeCardsVisible=false
 for _,quick in ipairs(quicks) do if quick then quick.Visible=false end end
 local function iconFor(name)
  local str=tostring(name or ""):upper()
  str=str:gsub("[^%w_]","")
  local tile=sidebarTiles:FindFirstChild("IconTile_"..str)
  return tile and tile:FindFirstChild("CategoryIcon")
 end
 local function setNavIcon(nav,name)
  local icon=iconFor(name)
  if not icon then return end
  local original=nav:FindFirstChild("CategoryIcon")
  local pos=original and original.Position or UDim2.fromOffset(14,9)
  local size=original and original.Size or UDim2.fromOffset(24,24)
  if original then original:Destroy() end
  local newIcon=icon:Clone()
  newIcon.Name="CategoryIcon"
  newIcon.Position=pos
  newIcon.Size=size
  newIcon.Parent=nav
 end

 local function showPage(id)
  if not alive() then return end
  local page
  local title,subtitle
  if id=="home" then
   page=home
   title="INICIO"
   subtitle=tostring(config.Subtitle or "")
  else
   local tab=tabs[id]
   if not tab then return end
   page=tab.Page
   title=tab.Name
   subtitle=tab.Description
  end
  activeId=id
  workspacePanel.CurrentPageTitle.Text=title
  workspacePanel.CurrentPageDescription.Text=subtitle
  workspacePanel.SearchFrame.Visible=false
  home.Visible=(id=="home")
  navHome.BackgroundColor3=id=="home" and Color3.fromRGB(53,25,37) or Color3.fromRGB(16,17,23)
  local homeInd=navHome:FindFirstChild("ActiveIndicator")
  if homeInd then homeInd.BackgroundColor3=id=="home" and Color3.fromRGB(235,67,110) or Color3.fromRGB(16,17,23) end
  for key,tab in pairs(tabs) do
   local chosen=(key==id)
   tab.Page.Visible=chosen
   tab.Nav.BackgroundColor3=chosen and Color3.fromRGB(53,25,37) or Color3.fromRGB(16,17,23)
   local ind=tab.Nav:FindFirstChild("ActiveIndicator")
   if ind then ind.BackgroundColor3=chosen and Color3.fromRGB(235,67,110) or Color3.fromRGB(16,17,23) end
  end
 end
 keep(navHome.Activated:Connect(function() showPage("home") end))

 local win={Gui=gui,Window=window,Version=DanloUI.Version}
 function win:Notify(status,name) notify(status,name) end
 function win:SetVisible(state) if alive() then window.Visible=(state==true) end end
 function win:ToggleVisible() if alive() then window.Visible=not window.Visible end end
 function win:SelectTab(id)
  local tab=tabs[id]
  if tab then showPage(id) elseif id=="home" then showPage("home") end
 end
 function win:GetTab(id) return tabs[id] end
 function win:SetHomeCardsVisible(state)
  homeCardsVisible=(state==true)
  for i,quick in ipairs(quicks) do
   if quick then quick.Visible=homeCardsVisible and quickAssigned[i]==true end
  end
 end
 function win:SetHomeIconGalleryVisible(state)
  sidebarTiles.Visible=(state==true)
 end
 function win:CloneTemplate(name)
  local resource=templates[tostring(name)]
  if name=="OriginalHome" then resource=home end
  if name=="IconPalette" then resource=sidebarTiles end
  return resource and resource:Clone() or nil
 end
 function win:Destroy()
  if not running then return end
  running=false
  for _,conn in ipairs(connections) do conn:Disconnect() end
  stopNotifications()
  for _,tw in ipairs(animations) do pcall(function() tw:Cancel() end) end
  for _,tmpl in pairs(templates) do tmpl:Destroy() end
  navTemplate:Destroy()
  pageTemplate:Destroy()
  gui:Destroy()
  if DanloUI._activeWindow==win then DanloUI._activeWindow=nil end
 end

 local function positionCard(page)
  local i=(pageCards[page] or 0)
  pageCards[page]=i+1
  local x=3+(i%2)*297
  local y=(page==home and 150 or 3)+math.floor(i/2)*95
  page.CanvasSize=UDim2.fromOffset(0,math.max(332,y+95))
  return UDim2.fromOffset(x,y)
 end
 local function createCard(tab,kind,cfg)
  cfg=cfgTable(cfg)
  local card=templates[kind]:Clone()
  card.Name="Control_"..kind.."_"..tostring(#tab.Controls+1)
  card.Position=positionCard(tab.Page)
  card.Visible=true
  card.Parent=tab.Page
  local name=setCardText(card,kind,cfg)
  return card,name,cfg
 end
 local function makeHandle(card)
  local h={Instance=card}
  function h:Destroy() if card.Parent then card:Destroy() end end
  return h
 end

 function win:CreateTab(args)
  local info=cfgTable(args)
  local tabName=makeName(info.Name or info.Title or "PESTAÑA")
  local isHome=tabName:upper()=="INICIO"
  if isHome and win.Home then return win.Home end
  local id,nav,page
  if isHome then
   id="home"
   nav=navHome
   page=home
  else
   nextId=nextId+1
   id="tab"..tostring(nextId)
   nav=navTemplate:Clone()
   nav.Name="Nav_"..id
   nav.Position=UDim2.fromOffset(10,53+(nextId-1)*50)
   nav.NavLabel.Text=tabName
   nav.NavLabel.TextTruncate=Enum.TextTruncate.AtEnd
   nav.IndexChip.IndexText.Text=tostring(nextId)
   setNavIcon(nav,info.Icon or "EXTRAS")
   nav.Parent=navArea
   navArea.CanvasSize=UDim2.fromOffset(0,math.max(351,53+nextId*50))
   page=pageTemplate:Clone()
   page.Name="Page_"..id
   page.Visible=false
   page.CanvasSize=UDim2.fromOffset(0,332)
   page.Parent=host
   keep(nav.Activated:Connect(function()showPage(id)end))
  end
  pageCards[page]=0
  local tab={Name=tabName,Description=tostring(info.Description or ""),Icon=info.Icon,Page=page,Nav=nav,Controls={},Id=id}
  tabs[id]=tab
  if not isHome and nextId<=3 then
   local quick=quicks[nextId]
   if quick then
    quickAssigned[nextId]=true
    quick.Visible=homeCardsVisible
    quick.CategoryTitle.Text=tabName
    quick.CategoryDescription.Text=tab.Description
    local realIcon=iconFor(info.Icon or "EXTRAS")
    if realIcon then
     local oldIcon=quick:FindFirstChild("CategoryIcon")
     local copy=realIcon:Clone()
     copy.Name="CategoryIcon"
     if oldIcon then copy.Position=oldIcon.Position;copy.Size=oldIcon.Size;oldIcon:Destroy() end
     copy.Parent=quick
    end
    keep(quick.Activated:Connect(function() showPage(id) end))
   end
  end
  function tab:Select() showPage(id) end
  function tab:CreateToggle(args2)
   local card,name,cfg=createCard(tab,"Toggle",args2)
   local button=card.Toggle_Example
   local enabled=(cfg.Default==true)
   local handle=makeHandle(card)
   local function render() styleButton(button,enabled and "ON" or "OFF",enabled) end
   function handle:Get() return enabled end
   function handle:Set(val,silent)
    local nextState=(val==true)
    if nextState==enabled then return true end
    if not silent and not safeCall(cfg.Callback,nextState) then return false end
    enabled=nextState
    render()
    if not silent and cfg.Notify~=false then notify(enabled,name) end
    return true
   end
   keep(button.Activated:Connect(function()handle:Set(not enabled)end))
   render()
   table.insert(tab.Controls,handle)
   return handle
  end

  function tab:CreateSlider(args2)
   local card,name,cfg=createCard(tab,"Slider",args2)
   local min=tonumber(cfg.Min) or 0
   local max=tonumber(cfg.Max) or 100
   if max<=min then max=min+1 end
   local step=math.max(0.000001,tonumber(cfg.Increment or cfg.Step) or 1)
   local value=math.clamp(tonumber(cfg.Default) or min,min,max)
   local enabled=(cfg.Enabled==true)
   local button=card:FindFirstChild("Toggle_Slider")
   if not button then
    button=templates.Toggle.Toggle_Example:Clone()
    button.Name="Toggle_Slider"
    button.Parent=card
   end
   button.Position=UDim2.fromOffset(207,9)
   button.Size=UDim2.fromOffset(64,21)
   button.TextSize=11
   button.ZIndex=8
   button.AutoButtonColor=false
   local track=card.SliderTrack
   local fill=track.SliderFill
   local knob=track.SliderKnob
   local label=card.SliderValue
   local handle=makeHandle(card)
   local function redraw()
    local ratio=(value-min)/(max-min)
    fill.Size=UDim2.new(ratio,0,1,0)
    knob.Position=UDim2.new(ratio,-knob.Size.X.Offset/2,0.5,-knob.Size.Y.Offset/2)
    label.Text=string.format("%g",value)
    styleButton(button,enabled and "ON" or "OFF",enabled)
    fill.BackgroundColor3=enabled and BORDER_GREEN or Color3.fromRGB(240,72,116)
    label.TextColor3=enabled and ACTIVE_GREEN or INACTIVE_RED
   end
   function handle:Get() return value,enabled end
   function handle:SetValue(number,silent)
    local incoming=math.clamp(tonumber(number) or value,min,max)
    incoming=math.clamp(math.floor((incoming-min)/step+0.5)*step+min,min,max)
    if incoming==value then return true end
    if not silent and not safeCall(cfg.Callback,incoming,enabled) then return false end
    value=incoming
    redraw()
    return true
   end
   function handle:SetEnabled(state,silent)
    local incoming=(state==true)
    if incoming==enabled then return true end
    if not silent and not safeCall(cfg.OnToggle,incoming,value) then return false end
    if not silent and not safeCall(cfg.Callback,value,incoming) then return false end
    enabled=incoming
    redraw()
    if not silent and cfg.Notify~=false then notify(enabled,name) end
    return true
   end
   local dragging=false
   local function pointer(x)
    if track.AbsoluteSize.X<1 then return end
    local frac=math.clamp((x-track.AbsolutePosition.X)/track.AbsoluteSize.X,0,1)
    handle:SetValue(min+(max-min)*frac)
   end
   keep(track.InputBegan:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
     dragging=true
     pointer(input.Position.X)
    end
   end))
   keep(knob.InputBegan:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
     dragging=true
     pointer(input.Position.X)
    end
   end))
   keep(UIS.InputChanged:Connect(function(input)
    if dragging and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then
     pointer(input.Position.X)
    end
   end))
   keep(UIS.InputEnded:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end
   end))
   keep(button.Activated:Connect(function() handle:SetEnabled(not enabled) end))
   redraw()
   table.insert(tab.Controls,handle)
   return handle
  end

  function tab:CreateButton(args2)
   local card,name,cfg=createCard(tab,"Execute",args2)
   local button=card.Execute_Example
   button.Position=UDim2.fromOffset(150,52)
   button.Size=UDim2.fromOffset(120,22)
   button.TextSize=10
   local runningAction=false
   local handle=makeHandle(card)
   function handle:IsExecuting() return runningAction end
   function handle:Run()
    if runningAction then return false end
    runningAction=true
    styleButton(button,"EJECUTÁNDOSE",true)
    task.spawn(function()
     local started=os.clock()
     local ok=safeCall(cfg.Callback)
     task.wait(math.max(0,0.7-(os.clock()-started)))
     if alive() and card.Parent then
      styleButton(button,"EJECUTAR",false)
     end
     runningAction=false
     if not ok then warn("[DanloUI] No se completó: "..name) end
    end)
    return true
   end
   keep(button.Activated:Connect(function()handle:Run()end))
   styleButton(button,"EJECUTAR",false)
   table.insert(tab.Controls,handle)
   return handle
  end
  tab.CreateExecuteButton=tab.CreateButton

  function tab:CreateOpenButton(args2)
   local card,name,cfg=createCard(tab,"Open",args2)
   local button=card.Open_Example
   button.Position=UDim2.fromOffset(170,52)
   button.Size=UDim2.fromOffset(100,22)
   button.TextSize=10
   local opened=(cfg.Default==true)
   local pending=false
   local handle=makeHandle(card)
   function handle:IsOpen() return opened end
   function handle:SetOpen(state,silent)
    if pending then return false end
    local desired=(state==true)
    if desired==opened then return true end
    if not silent and not safeCall(cfg.Callback,desired) then return false end
    if not desired then
     opened=false
     styleButton(button,"CERRADO",false)
     return true
    end
    pending=true
    styleButton(button,"ABRIENDO",true)
    task.delay(0.5,function()
     if not alive() or not card.Parent then pending=false return end
     opened=true
     pending=false
     styleButton(button,"ABIERTO",true)
    end)
    return true
   end
   keep(button.Activated:Connect(function()handle:SetOpen(not opened)end))
   styleButton(button,opened and "ABIERTO" or "ABRIR",opened)
   table.insert(tab.Controls,handle)
   return handle
  end
  tab.CreateOpen=tab.CreateOpenButton
  function tab:Clear()
   for _,h in ipairs(tab.Controls) do h:Destroy() end
   table.clear(tab.Controls)
   pageCards[tab.Page]=0
   tab.Page.CanvasSize=UDim2.fromOffset(0,332)
  end
  return tab
 end

 win.Home=win:CreateTab({Name="INICIO",Icon="INICIO"})
 local function watch(object)
  if object:IsA("UIGradient") and object.Name=="NeonFlow" then
   gradients[object]=true
  elseif object:IsA("TextButton") then
   local stroke=object:FindFirstChildOfClass("UIStroke")
   if stroke then
    local base=stroke.Thickness
    keep(object.MouseEnter:Connect(function()
     if alive() and stroke.Parent then
      TweenService:Create(stroke,TweenInfo.new(0.16),{Thickness=base+0.5}):Play()
     end
    end))
    keep(object.MouseLeave:Connect(function()
     if alive() and stroke.Parent then
      TweenService:Create(stroke,TweenInfo.new(0.2),{Thickness=base}):Play()
     end
    end))
   end
  elseif object:IsA("Frame") and object.Name=="IconGlow" then
   local tw=TweenService:Create(object,TweenInfo.new(1.3,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{BackgroundTransparency=0.6})
   table.insert(animations,tw)
   tw:Play()
  end
 end
 for _,child in ipairs(gui:GetDescendants()) do watch(child) end
 keep(gui.DescendantAdded:Connect(watch))
 keep(gui.DescendantRemoving:Connect(function(child)
  if child:IsA("UIGradient") then gradients[child]=nil end
 end))
 local elapsed=0
 keep(RunService.Heartbeat:Connect(function(dt)
  if not alive() then return end
  if not window.Visible then return end
  elapsed=elapsed+math.min(dt,0.08)
  for grad in pairs(gradients) do
   if not grad.Parent then gradients[grad]=nil else
    local visible=true
    local current=grad.Parent
    while current and current~=gui do
     if current:IsA("GuiObject") and not current.Visible then visible=false;break end
     current=current.Parent
    end
    if visible then grad.Rotation=(elapsed*48)%360 end
   end
  end
  if home.Visible then
   local hero=home:FindFirstChild("Hero")
   if hero then
    for i=1,3 do
     local orbit=hero:FindFirstChild("Orbit"..i)
     if orbit then orbit.Rotation=(elapsed*(i%2==0 and -9 or 12)+i*25)%360 end
    end
   end
  end
 end))
 local dragging=false
 local dragStart
 local positionStart
 keep(header.InputBegan:Connect(function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
   dragging=true;dragStart=input.Position;positionStart=window.Position
  end
 end))
 keep(UIS.InputChanged:Connect(function(input)
  if not dragging or not dragStart or not positionStart then return end
  if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then
   local d=input.Position-dragStart
   window.Position=UDim2.new(positionStart.X.Scale,positionStart.X.Offset+d.X,positionStart.Y.Scale,positionStart.Y.Offset+d.Y)
  end
 end))
 keep(UIS.InputEnded:Connect(function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end
 end))
 local scale=window:FindFirstChild("ResponsiveScale")
 local function resize()
  if not scale then return end
  local cam=workspace.CurrentCamera
  if not cam then return end
  local size=cam.ViewportSize
  scale.Scale=math.clamp(math.min((size.X-28)/830,(size.Y-44)/532),0.4,1.15)
 end
 resize()
 local cam=workspace.CurrentCamera
 if cam then keep(cam:GetPropertyChangedSignal("ViewportSize"):Connect(resize)) end
 local keybind=config.Keybind or Enum.KeyCode.RightShift
 if type(keybind)=="string" then keybind=Enum.KeyCode[keybind] or Enum.KeyCode.RightShift end
 keep(UIS.InputBegan:Connect(function(input,processed)
  if not processed and input.KeyCode==keybind then win:ToggleVisible() end
 end))
 keep(header.MinimizeButton.Activated:Connect(function()win:SetVisible(false)end))
 keep(header.CloseButton.Activated:Connect(function()win:SetVisible(false)end))
 local text=config.Title
 if type(text)=="string" and text~="" and text~="DANLOHUB" then
  local subtitle=header:FindFirstChild("BrandSubtitle")
  if subtitle and subtitle:IsA("TextLabel") then subtitle.Text=text end
 end
 showPage("home")
 window.Visible=true
 DanloUI._activeWindow=win
 return win
end

return DanloUI
